const BY_TAG = new Map<string, string>();
for (const [name, e] of Object.entries(BAMBU_CATALOG)) {
  const mid = e.material_id.toUpperCase();
  BY_TAG.set(`${mid}\t${e.variant_id}`, name);
  if (mid === "GFA05") BY_TAG.set(`GFA06\t${e.variant_id}`, name);
}

/** Normalize variant id: A01-K01 -> A01-K1 (same idea as Python). */
function normalizeVariantTagId(raw: string): string {
  return raw.trim().replace(/-([A-Z]+?)0*(\d+)$/i, (_, letters: string, digits: string) => {
    const n = parseInt(digits, 10);
    return `-${letters}${n}`;
  });
}

/** Lookup catalog display name from tray_info_material + tray_info_variant. */
export function catalogNameForBambuTag(materialId: string, variantId: string): string | undefined {
  const mid = materialId.trim().toUpperCase();
  let vid = variantId.trim();
  let name = BY_TAG.get(`${mid}\t${vid}`);
  if (name) return name;
  const vid2 = normalizeVariantTagId(vid);
  if (vid2 !== vid) name = BY_TAG.get(`${mid}\t${vid2}`);
  return name;
}
